import React, { useState } from 'react'
import { darkThemeColors } from '../../styles/theme'
import Tooltip from '@mui/material/Tooltip'
import IconButton from '@mui/material/IconButton'

interface TopToolbarProps {
  projectName: string
  onProjectNameChange: (name: string) => void
  zoomLevel: number
  onZoomIn: () => void
  onZoomOut: () => void
  onFitView: () => void
  onAutoLayout: () => void
  showGrid: boolean
  onToggleGrid: () => void
  onDownload: () => void
  onOpenSettings: () => void
  onSave?: () => void
}

const TopToolbar: React.FC<TopToolbarProps> = ({
  projectName,
  onProjectNameChange,
  zoomLevel,
  onZoomIn,
  onZoomOut,
  onFitView,
  onAutoLayout,
  showGrid,
  onToggleGrid,
  onDownload,
  onOpenSettings,
  onSave,
}) => {
  const [isEditingName, setIsEditingName] = useState(false)
  const [mcpStatus, setMcpStatus] = useState<'connected' | 'disconnected' | 'connecting'>('connected')

  const toolbarStyle: React.CSSProperties = {
    height: '48px',
    backgroundColor: darkThemeColors.bgSecondary,
    borderBottom: `1px solid ${darkThemeColors.border}`,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '0 16px',
    position: 'relative',
    zIndex: 10,
  }

  const leftSectionStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
  }

  const centerSectionStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    position: 'absolute',
    left: '50%',
    transform: 'translateX(-50%)',
  }

  const rightSectionStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  }

  const buttonStyle: React.CSSProperties = {
    backgroundColor: 'transparent',
    color: darkThemeColors.textSecondary,
    border: 'none',
    padding: '6px 12px',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '13px',
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    fontFamily: 'inherit',
  }

  const buttonHoverStyle: React.CSSProperties = {
    ...buttonStyle,
    backgroundColor: darkThemeColors.bgTertiary,
    color: darkThemeColors.textPrimary,
  }

  const iconButtonStyle: React.CSSProperties = {
    backgroundColor: 'transparent',
    color: darkThemeColors.textSecondary,
    border: 'none',
    width: '32px',
    height: '32px',
    borderRadius: '6px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '16px',
  }

  return (
    <div style={toolbarStyle}>
      {/* Left Section: MCP Status + Project Name */}
      <div style={leftSectionStyle}>
        {/* MCP Status Indicator */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <div
            style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: mcpStatus === 'connected' ? darkThemeColors.accentGreen : 
                             mcpStatus === 'connecting' ? darkThemeColors.accentYellow : 
                             darkThemeColors.accentRed,
              boxShadow: mcpStatus === 'connected' ? `0 0 8px ${darkThemeColors.accentGreen}` : 'none',
            }}
          />
          <span style={{ fontSize: '12px', color: darkThemeColors.textSecondary }}>
            MCP {mcpStatus === 'connected' ? '已就绪' : mcpStatus === 'connecting' ? '连接中...' : '未连接'}
          </span>
        </div>

        {/* Divider */}
        <div style={{ width: '1px', height: '24px', backgroundColor: darkThemeColors.border }} />

        {/* Project Name Input */}
        {isEditingName ? (
          <input
            type="text"
            value={projectName}
            onChange={(e) => onProjectNameChange(e.target.value)}
            onBlur={() => setIsEditingName(false)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') setIsEditingName(false)
            }}
            autoFocus
            style={{
              backgroundColor: darkThemeColors.bgTertiary,
              border: `1px solid ${darkThemeColors.accentBlue}`,
              borderRadius: '4px',
              color: darkThemeColors.textPrimary,
              fontSize: '14px',
              padding: '4px 8px',
              outline: 'none',
              width: '200px',
            }}
          />
        ) : (
          <div
            onClick={() => setIsEditingName(true)}
            style={{
              cursor: 'pointer',
              color: darkThemeColors.textPrimary,
              fontSize: '14px',
              padding: '4px 8px',
              borderRadius: '4px',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
            }}
          >
            {projectName || '未命名项目'}
          </div>
        )}
      </div>

      {/* Center Section: Template Library, Asset Library, Cloud ComfyUI */}
      <div style={centerSectionStyle}>
        <button
          style={buttonStyle}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
            e.currentTarget.style.color = darkThemeColors.textPrimary
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent'
            e.currentTarget.style.color = darkThemeColors.textSecondary
          }}
          title="模板库"
        >
          📚 模板库
        </button>

        <button
          style={buttonStyle}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
            e.currentTarget.style.color = darkThemeColors.textPrimary
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent'
            e.currentTarget.style.color = darkThemeColors.textSecondary
          }}
          title="资产库"
        >
          📦 资产库
        </button>

        <button
          style={buttonStyle}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
            e.currentTarget.style.color = darkThemeColors.textPrimary
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent'
            e.currentTarget.style.color = darkThemeColors.textSecondary
          }}
          title="云端 ComfyUI"
        >
          ☁️ 云端 ComfyUI
        </button>
      </div>

      {/* Right Section: Zoom, Download, Grid, Navigation, Arrange, Settings */}
      <div style={rightSectionStyle}>
        {/* Save Button */}
        <Tooltip title="保存工作流" placement="bottom">
          <button
            style={{
              ...buttonStyle,
              backgroundColor: darkThemeColors.accentBlue,
              color: 'white',
              padding: '6px 16px',
            }}
            onClick={onSave}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.accentBlue + 'dd'
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.accentBlue
            }}
          >
            💾 保存
          </button>
        </Tooltip>

        {/* Divider */}
        <div style={{ width: '1px', height: '24px', backgroundColor: darkThemeColors.border }} />
        {/* Zoom Level Display */}
        <div
          style={{
            color: darkThemeColors.textSecondary,
            fontSize: '12px',
            padding: '4px 8px',
            backgroundColor: darkThemeColors.bgTertiary,
            borderRadius: '4px',
            minWidth: '48px',
            textAlign: 'center',
          }}
        >
          {Math.round(zoomLevel * 100)}%
        </div>

        {/* Divider */}
        <div style={{ width: '1px', height: '24px', backgroundColor: darkThemeColors.border }} />

        {/* Download Button */}
        <Tooltip title="下载工作流" placement="bottom">
          <button
            style={iconButtonStyle}
            onClick={onDownload}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
              e.currentTarget.style.color = darkThemeColors.textPrimary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = darkThemeColors.textSecondary
            }}
          >
            ⬇️
          </button>
        </Tooltip>

        {/* Grid Toggle */}
        <Tooltip title={showGrid ? '隐藏网格' : '显示网格'} placement="bottom">
          <button
            style={{
              ...iconButtonStyle,
              color: showGrid ? darkThemeColors.accentBlue : darkThemeColors.textSecondary,
            }}
            onClick={onToggleGrid}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
              e.currentTarget.style.color = showGrid ? darkThemeColors.accentBlue : darkThemeColors.textPrimary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = showGrid ? darkThemeColors.accentBlue : darkThemeColors.textSecondary
            }}
          >
            ⊞
          </button>
        </Tooltip>

        {/* Divider */}
        <div style={{ width: '1px', height: '24px', backgroundColor: darkThemeColors.border }} />

        {/* Navigation Buttons */}
        <Tooltip title="适应视图" placement="bottom">
          <button
            style={iconButtonStyle}
            onClick={onFitView}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
              e.currentTarget.style.color = darkThemeColors.textPrimary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = darkThemeColors.textSecondary
            }}
          >
            ⊡
          </button>
        </Tooltip>

        <Tooltip title="整理布局" placement="bottom">
          <button
            style={iconButtonStyle}
            onClick={onAutoLayout}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
              e.currentTarget.style.color = darkThemeColors.textPrimary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = darkThemeColors.textSecondary
            }}
          >
            ⊟
          </button>
        </Tooltip>

        {/* Settings Button */}
        <Tooltip title="设置" placement="bottom">
          <button
            style={iconButtonStyle}
            onClick={onOpenSettings}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = darkThemeColors.bgTertiary
              e.currentTarget.style.color = darkThemeColors.textPrimary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = darkThemeColors.textSecondary
            }}
          >
            ⚙️
          </button>
        </Tooltip>
      </div>
    </div>
  )
}

export default TopToolbar
