import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { workflowService } from '../services/workflowService'
import { Workflow } from '../types'

export default function DashboardPage() {
  const [workflows, setWorkflows] = useState<Workflow[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const navigate = useNavigate()

  // 加载工作流列表
  useEffect(() => {
    loadWorkflows()
  }, [])

  const loadWorkflows = async () => {
    try {
      const response = await workflowService.getWorkflows()
      if (response.code === 0 && response.data) {
        setWorkflows(response.data)
      }
    } catch (error) {
      console.error('加载工作流失败:', error)
    } finally {
      setIsLoading(false)
    }
  }

  // 创建工作流
  const handleCreateWorkflow = async () => {
    try {
      const response = await workflowService.createWorkflow({
        name: '新建工作流'
      })
      if (response.code === 0 && response.data) {
        navigate(`/workflow/${response.data.id}`)
      }
    } catch (error) {
      console.error('创建工作流失败:', error)
    }
  }

  // 删除工作流
  const handleDeleteWorkflow = async (id: string) => {
    if (!confirm('确定要删除这个工作流吗？')) return

    try {
      await workflowService.deleteWorkflow(id)
      loadWorkflows()
    } catch (error) {
      console.error('删除工作流失败:', error)
    }
  }

  if (isLoading) {
    return <div>Loading...</div>
  }

  return (
    <div style={{ padding: 30, maxWidth: 1200, margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 30 }}>
        <h1>我的工作流</h1>
        <button
          onClick={handleCreateWorkflow}
          style={{
            padding: '10px 20px',
            backgroundColor: '#1976d2',
            color: 'white',
            border: 'none',
            borderRadius: 5,
            cursor: 'pointer'
          }}
        >
          + 新建工作流
        </button>
      </div>

      {workflows.length === 0 ? (
        <div style={{ textAlign: 'center', padding: 50, color: '#999' }}>
          <p>还没有工作流</p>
          <p>点击"新建工作流"开始创建</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 20 }}>
          {workflows.map((workflow) => (
            <div
              key={workflow.id}
              style={{
                padding: 20,
                border: '1px solid #ddd',
                borderRadius: 8,
                backgroundColor: 'white',
                cursor: 'pointer'
              }}
              onClick={() => navigate(`/workflow/${workflow.id}`)}
            >
              <h3 style={{ marginTop: 0 }}>{workflow.name}</h3>
              {workflow.description && (
                <p style={{ color: '#666', fontSize: 14 }}>{workflow.description}</p>
              )}
              <div style={{ fontSize: 12, color: '#999', marginTop: 10 }}>
                更新于 {new Date(workflow.updatedAt).toLocaleDateString()}
              </div>
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleDeleteWorkflow(workflow.id)
                }}
                style={{
                  marginTop: 10,
                  padding: '5px 10px',
                  backgroundColor: '#f44336',
                  color: 'white',
                  border: 'none',
                  borderRadius: 3,
                  cursor: 'pointer'
                }}
              >
                删除
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
